import React from 'react';
import {useCurrentFrame, useVideoConfig, AbsoluteFill} from 'remotion';
import {ThreeCanvas} from '@remotion/three';
export const SUBS = {arriba: 3000, size: 1, acento: '#ffd84d'};
export const SFX = [];
export const Escena: React.FC = () => {
  const f = useCurrentFrame();
  const {width, height} = useVideoConfig();
  return <AbsoluteFill style={{background: '#113f4d'}}><ThreeCanvas width={width} height={height}><ambientLight intensity={1} /><directionalLight position={[3, 5, 5]} intensity={2} /><group position={[Math.sin(f * 0.05) * 1.2, Math.sin(f * 0.11) * 0.8, 0]} rotation={[f * 0.14, 0, 0.35]}><mesh><cylinderGeometry args={[1.4, 1.4, 0.3, 48]} /><meshStandardMaterial color="#ffc93c" /></mesh><mesh position={[0, 0.17, 0]}><boxGeometry args={[1.8, 0.04, 0.4]} /><meshStandardMaterial color="#b5650d" /></mesh><mesh position={[0, -0.17, 0]}><boxGeometry args={[0.4, 0.04, 1.8]} /><meshStandardMaterial color="#b5650d" /></mesh></group></ThreeCanvas></AbsoluteFill>;
};
